      error: {
        ok: false,
        fieldErrors,
        values: {
          title,
          priority,
          description
        }
      }
    };
  }

  return {
    ok: true,
    value: {
      title,
      priority: priority as CreateCaseCommand["priority"],
      description: description || undefined
    }
  };
}
